using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Diagnostics;using System.Threading;using System.Windows.Forms;using Gunt.ControlCenter.Models;
namespace Gunt.ControlCenter.Services {
 public sealed partial class DesktopService {
  public Func<Dictionary<string,object>> WorkspaceOverride;
  Dictionary<string,object> OwnedWorkspace(){return WorkspaceOverride!=null?WorkspaceOverride():Workspace();}
  public AutomationStore Automation(){var store=Local("smart-automation",()=>new AutomationStore());if(store==null||store.SchemaVersion!=1||store.Rules==null)throw new InvalidDataException("자동화 규칙 형식을 확인하세요.");return store;}
  public void SaveRule(AutomationRule rule){if(String.IsNullOrWhiteSpace(rule.Name)||rule.Name.Length>80||!System.Text.RegularExpressions.Regex.IsMatch(rule.Id??"",@"^[a-zA-Z0-9_-]{1,80}$"))throw new ArgumentException("규칙 이름·ID를 확인하세요.");if(!new[]{"session-started","session-ended","application-running","ac-connected","battery","monitor-changed"}.Contains(rule.Trigger))throw new ArgumentException("지원하지 않는 자동화 조건입니다.");if(!new[]{"profile","restore-owned","monitor-show","monitor-hide","wallpaper-pause","wallpaper-play","open-project","session"}.Contains(rule.Action))throw new ArgumentException("지원하지 않는 자동화 동작입니다.");if(rule.CooldownSeconds<10||rule.CooldownSeconds>86400||rule.Priority<0||rule.Priority>100)throw new ArgumentException("재실행 간격은 10–86400초, 우선순위는 0–100입니다.");if(!new[]{"any","ac","battery"}.Contains(rule.Power))throw new ArgumentException("전원 조건을 확인하세요.");if(rule.Trigger=="application-running")ValidateProcessName(rule.TriggerValue);foreach(var app in rule.Exceptions)ValidateProcessName(app);if(rule.Action=="profile"&&!Profiles().Any(p=>p.Id==rule.Value))throw new ArgumentException("실제 작업공간 프로필을 선택하세요.");if(rule.Action=="open-project"&&!Projects().Any(p=>p.Id==rule.Value))throw new ArgumentException("실제 프로젝트를 선택하세요.");if(rule.Action=="session"){var session=Sessions().Presets.FirstOrDefault(p=>p.Id==rule.Value);if(session==null||!session.AllowAutomation||session.Actions.Any(a=>a.Enabled&&a.Kind=="command"))throw new ArgumentException("자동 실행을 허용하고 프로젝트 명령이 없는 세션만 선택하세요.");if(rule.Trigger.StartsWith("session-"))throw new ArgumentException("세션 이벤트에서 세션을 다시 시작하는 규칙은 허용하지 않습니다.");}var data=Automation();var index=data.Rules.FindIndex(x=>x.Id==rule.Id);if(index<0)data.Rules.Add(rule);else data.Rules[index]=rule;SaveLocal("smart-automation",data);}
  static string ProcessName(string name){return name.EndsWith(".exe",StringComparison.OrdinalIgnoreCase)?name.Substring(0,name.Length-4):name;}
  static void ValidateProcessName(string name){if(!System.Text.RegularExpressions.Regex.IsMatch(name??"",@"^[\p{L}\p{N}_.-]{1,80}$"))throw new ArgumentException("프로세스 이름만 입력하세요. 경로·명령 인수는 사용할 수 없습니다.");}
  public void DeleteRule(string id){var data=Automation();data.Rules.RemoveAll(x=>x.Id==id);SaveLocal("smart-automation",data);}
  public string AutomationHistory(){var s=State("automation-history");if(!s.ContainsKey("Events"))return "규칙 실행 기록이 없습니다.";var rows=Json.Deserialize<List<Dictionary<string,object>>>(Json.Serialize(s["Events"]));return String.Join("\n",rows.Select(row=>S(row,"Time")+" · "+S(row,"Name")+" · "+S(row,"Outcome")+" · "+S(row,"Reason")));}
  void RuleLog(AutomationRule rule,string outcome,string reason){var state=State("automation-history");var list=state.ContainsKey("Events")?Json.Deserialize<List<Dictionary<string,object>>>(Json.Serialize(state["Events"])):new List<Dictionary<string,object>>();list.Insert(0,new Dictionary<string,object>{{"Time",DateTimeOffset.Now.ToString("o")},{"RuleId",rule.Id},{"Name",rule.Name},{"Trigger",rule.Trigger},{"Outcome",outcome},{"Reason",reason}});GuntConfiguration.Atomic(Root,Path.Combine(Root,"state","automation-history.json"),Json.Serialize(new {Events=list.Take(100).ToArray()}),false);}
  public void AutomationEvent(string trigger,string value=""){foreach(var rule in Automation().Rules.Where(r=>r.Enabled&&r.Trigger==trigger&&(String.IsNullOrEmpty(r.TriggerValue)||r.TriggerValue==value)).OrderByDescending(r=>r.Priority))try{RunAutomationRule(rule.Id);}catch(Exception e){RuleLog(rule,"실패",e.Message);}}
  public string RunAutomationRule(string id){var rule=Automation().Rules.FirstOrDefault(r=>r.Id==id);if(rule==null||!rule.Enabled)return "사용하지 않는 규칙은 실행하지 않습니다.";using(var mutex=new Mutex(false,ScopedMutex("AutomationExecution"))){if(!mutex.WaitOne(0))return "다른 규칙이 실행 중이어서 건너뜁니다.";try{var times=State("automation-times");DateTimeOffset last;if(DateTimeOffset.TryParse(S(times,id),out last)&&DateTimeOffset.Now-last<TimeSpan.FromSeconds(rule.CooldownSeconds))return "재실행 대기 시간입니다.";var power=SystemInformation.PowerStatus.PowerLineStatus;if((rule.Power=="ac"&&power!=PowerLineStatus.Online)||(rule.Power=="battery"&&power!=PowerLineStatus.Offline))return "전원 조건이 달라 건너뜁니다.";foreach(string process in rule.Exceptions){var matches=Process.GetProcessesByName(ProcessName(process));try{if(matches.Length>0)return "예외 앱이 실행 중이어서 건너뜁니다.";}finally{foreach(var p in matches)p.Dispose();}}if(rule.Trigger=="application-running"&&Process.GetProcessesByName(ProcessName(rule.TriggerValue)).Length==0)return "조건 앱이 실행 중이 아닙니다.";if(rule.Trigger=="ac-connected"&&power!=PowerLineStatus.Online)return "AC 연결 상태가 아닙니다.";if(rule.Trigger=="battery"&&power!=PowerLineStatus.Offline)return "배터리 상태가 아닙니다.";
    if(rule.Action=="restore-owned"){string result=RestoreAutomationOwnership();RuleLog(rule,"확인",result);times[id]=DateTimeOffset.Now.ToString("o");GuntConfiguration.Atomic(Root,Path.Combine(Root,"state","automation-times.json"),Json.Serialize(times),false);return result;}
    var before=OwnedWorkspace();var active=State("profile-active");if(rule.Action=="profile")Action("profile-apply",rule.Value);else if(rule.Action=="open-project"){var p=Projects().First(x=>x.Id==rule.Value);LaunchDeveloper(p,"folder");}else if(rule.Action=="session"){var p=ActiveProject();StartSession(p,Sessions().Presets.First(s=>s.Id==rule.Value),false,true);}else Action(rule.Action);
    if(new[]{"profile","monitor-show","monitor-hide","wallpaper-pause","wallpaper-play"}.Contains(rule.Action))GuntConfiguration.Atomic(Root,Path.Combine(Root,"state","automation-owned.json"),Json.Serialize(new {Rule=rule.Id,Before=before,Expected=OwnedWorkspace(),ExpectedProfile=State("profile-active"),ExpectedPlayback=State("wallpaper-playback"),ActiveProfile=active,Consumed=false}),false);
    times[id]=DateTimeOffset.Now.ToString("o");GuntConfiguration.Atomic(Root,Path.Combine(Root,"state","automation-times.json"),Json.Serialize(times),false);RuleLog(rule,"실행 요청 전달",rule.Action+" · 조건 "+rule.Trigger);return rule.Name+" · 실행 요청을 전달했습니다.";
   }catch(Exception e){RuleLog(rule,"실패",e.Message);throw;}finally{mutex.ReleaseMutex();}}}
  public string RestoreAutomationOwnership(){var owner=State("automation-owned");if(owner.Count==0||B(owner,"Consumed"))return "복원할 자동화 소유 상태가 없습니다.";if(Json.Serialize(owner["Expected"])!=Json.Serialize(OwnedWorkspace())||(owner.ContainsKey("ExpectedProfile")&&Json.Serialize(owner["ExpectedProfile"])!=Json.Serialize(State("profile-active")))||(owner.ContainsKey("ExpectedPlayback")&&Json.Serialize(owner["ExpectedPlayback"])!=Json.Serialize(State("wallpaper-playback"))))return "이후 수동 변경이 있어 복원하지 않았습니다.";var before=Json.Deserialize<Dictionary<string,object>>(Json.Serialize(owner["Before"]));var current=Read("monitor");Apply(new[]{new SettingField{Config="monitor",Key="compact",Kind="bool",Label="간단한 모드",Original=Json.Serialize(current["compact"]),Value=B(before,"compact")}});Action(B(before,"monitorVisible")?"monitor-show":"monitor-hide");Action(B(before,"manualPaused")?"wallpaper-pause":"wallpaper-play");if(owner.ContainsKey("ActiveProfile"))GuntConfiguration.Atomic(Root,Path.Combine(Root,"state","profile-active.json"),Json.Serialize(owner["ActiveProfile"]),false);owner["Consumed"]=true;GuntConfiguration.Atomic(Root,Path.Combine(Root,"state","automation-owned.json"),Json.Serialize(owner),false);return "자동화가 소유하고 이후 변경되지 않은 작업공간 값만 복원했습니다.";}
 }
}
